import { GetObjectCommand, type S3Client } from '@aws-sdk/client-s3';
import { createWriteStream } from 'node:fs';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Transform } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { ObjectId, type Db } from 'mongodb';
// Album completion's own rule decides which members lack a duration, so the plan targets exactly what lookup cannot verify.
import { catalogReviewMemberDuration } from '../../administration/catalog/adminCatalogReviewCapture';
import { readyAudioStorageFilter } from '../../utils/audioStorageKey';
import { activeMediaObjectKeyForTrack, activeMediaTypeForTrack } from '../../utils/mediaStorageKey';
import { storedMediaRepresentationForTrack } from '../media/mediaRepresentationService';
// Measuring reuses the room audio decoder hardening; nothing here reads or changes room eligibility.
import { probeAudioDurationMs } from '../roomAudio/audioDurationProbe';
import { RoomAudioInspectionError } from '../roomAudio/roomAudioInspection';
import { formatDuration } from './audioMetadataService';

export interface AudioDurationBackfillOptions {
    /** Resume strictly after this track ID, as printed in a previous run's resumeAfter. */
    after?: string;
    /** Upper bound on candidate tracks reported (and, unless catalogOnly, downloaded) in one invocation. */
    limit: number;
    /** List candidates from the catalog without reading storage or decoding. */
    catalogOnly: boolean;
    logPath?: string;
}

/** `listed` is a catalog-only row; the others report what measuring the current source found. */
export type AudioDurationBackfillResult = 'listed' | 'wouldUpdate' | 'unprobeable' | 'stale' | 'failed';

/** One planned change; titles, storage keys and validators stay out of it. */
export interface AudioDurationBackfillEntry {
    type: 'track';
    mediaTrackId: string;
    albumId: string | null;
    discNumber: number | null;
    trackNumber: number | null;
    /** The stored representation: absent (never analyzed), readable, or present but malformed (never changed by the plan). */
    representation: 'missing' | 'stored' | 'invalid';
    result: AudioDurationBackfillResult;
    reason: 'source_changed' | 'storage_unavailable' | RoomAudioInspectionError['code'] | null;
    /** The decoded duration of the current source, when measured. */
    durationMs: number | null;
    /** Fields an approved apply would `$set`, each guarded by the unchanged source and the current value. */
    set: { 'mediaRepresentation.durationMs'?: number; duration?: string };
    /** The cursor that safely continues after this row. */
    resumeAfter: string;
}

export interface AudioDurationBackfillSummary {
    type: 'summary';
    dryRun: true;
    finished: boolean;
    resumeAfter: string | null;
    scanned: number;
    candidates: number;
    counts: Partial<Record<AudioDurationBackfillResult, number>>;
}

export interface AudioDurationBackfillDependencies {
    database: () => Db;
    storage: () => S3Client;
    bucket: string;
    probe: typeof probeAudioDurationMs;
    /** Persists one row before the run moves on; a thrown write ends the run. */
    record: (entry: AudioDurationBackfillEntry) => Promise<void> | void;
}

const id = /^[0-9a-f]{24}$/;
const maximumBytes = 512 * 1024 * 1024;
const pageSize = 100;
const usage = 'Use optional --after=<24 lowercase hex>, --limit=1..1000, --catalog-only and --log=<file>. '
    + 'This command only previews; it has no --apply.';

/** A fixed message keeps invalid CLI values and connection details out of command output. */
export class AudioDurationBackfillArgumentError extends Error {
    constructor() { super(usage); this.name = 'AudioDurationBackfillArgumentError'; }
}

/** Accepts only the documented flags; any write request is refused because no write path exists. */
export const parseAudioDurationBackfillArguments = (argv: readonly string[]): AudioDurationBackfillOptions => {
    const options: AudioDurationBackfillOptions = { limit: 100, catalogOnly: false };
    const seen = new Set<string>();
    for (const argument of argv) {
        const [name, value] = argument.includes('=') ? [argument.slice(0, argument.indexOf('=')), argument.slice(argument.indexOf('=') + 1)] : [argument, undefined];
        if (seen.has(name)) throw new AudioDurationBackfillArgumentError();
        seen.add(name);
        if (name === '--after' && value !== undefined && id.test(value)) options.after = value;
        else if (name === '--limit' && value !== undefined && /^\d{1,4}$/.test(value) && Number(value) >= 1 && Number(value) <= 1000) options.limit = Number(value);
        else if (name === '--catalog-only' && value === undefined) options.catalogOnly = true;
        else if (name === '--log' && value) options.logPath = value;
        else throw new AudioDurationBackfillArgumentError();
    }
    return options;
};

const ordinal = (value: unknown) => Number.isSafeInteger(value) && (value as number) > 0 ? value as number : null;
const s3Status = (error: unknown) => (error as { $metadata?: { httpStatusCode?: number } })?.$metadata?.httpStatusCode;

/**
 * Downloads the current object into a private temporary file and returns its size. A readable stored representation pins
 * the read to its validators, so a replaced object is reported stale rather than measured for the wrong record.
 */
const downloadSource = async (dependencies: AudioDurationBackfillDependencies, objectKey: string,
    pin: { etag: string; versionId: string | null; byteLength: number } | null, path: string, signal?: AbortSignal) => {
    const object = await dependencies.storage().send(new GetObjectCommand({ Bucket: dependencies.bucket, Key: objectKey,
        ...(pin ? { IfMatch: pin.etag, ...(pin.versionId ? { VersionId: pin.versionId } : {}) } : {}) }), { abortSignal: signal });
    const size = object.ContentLength;
    const body = object.Body as (NodeJS.ReadableStream & { destroy?: () => void }) | undefined;
    if (!body || pin && (object.ETag !== pin.etag || size !== pin.byteLength)) { body?.destroy?.(); return 'stale' as const; }
    if (!Number.isSafeInteger(size) || size! <= 0 || size! > maximumBytes) { body.destroy?.(); return 'unprobeable' as const; }
    let received = 0;
    const bound = new Transform({ transform(chunk: Buffer, _encoding, callback) {
        received += chunk.length;
        if (received > size!) callback(new Error('Source length mismatch.')); else callback(null, chunk);
    } });
    await pipeline(body, bound, createWriteStream(path, { flags: 'wx', mode: 0o600 }), { signal });
    return received === size ? size! : 'stale' as const;
};

/**
 * Previews the duration backfill for ready Audio whose duration metadata lookup cannot read: neither an exact
 * representation duration nor a whole-second display duration. Each candidate's current source is downloaded and
 * decoded to report the exact `mediaRepresentation.durationMs` (only on a readable unsupported representation that lacks
 * one) and the display `duration` an apply would set. It issues no database writes and only storage GETs.
 */
export const planAudioDurationBackfill = async (
    options: AudioDurationBackfillOptions,
    dependencies: AudioDurationBackfillDependencies,
    signal?: AbortSignal
): Promise<AudioDurationBackfillSummary> => {
    const tracks = dependencies.database().collection('audioTracks');
    const counts: AudioDurationBackfillSummary['counts'] = {};
    let cursor = options.after; let scanned = 0; let candidates = 0;
    for (;;) {
        const page = await tracks.find({ ...readyAudioStorageFilter, _id: { $type: 'objectId', ...(cursor ? { $gt: new ObjectId(cursor) } : {}) } },
            { projection: { s3Key: 1, mediaType: 1, videoAsset: 1, albumId: 1, discNumber: 1, trackNumber: 1, duration: 1, mediaRepresentation: 1 }, maxTimeMS: 5_000 })
            .sort({ _id: 1 }).limit(pageSize).toArray();
        for (const track of page) {
            signal?.throwIfAborted();
            cursor = String(track._id); scanned += 1;
            const objectKey = activeMediaObjectKeyForTrack(track);
            if (!objectKey || activeMediaTypeForTrack(track) !== 'audio'
                || catalogReviewMemberDuration({ mediaRepresentation: track.mediaRepresentation, duration: track.duration }) !== null) continue;
            candidates += 1;
            const stored = storedMediaRepresentationForTrack(track);
            const entry: AudioDurationBackfillEntry = { type: 'track', mediaTrackId: cursor, albumId: track.albumId ? String(track.albumId) : null,
                discNumber: ordinal(track.discNumber), trackNumber: ordinal(track.trackNumber),
                representation: stored ? 'stored' : track.mediaRepresentation == null ? 'missing' : 'invalid',
                result: 'listed', reason: null, durationMs: null, set: {}, resumeAfter: cursor };
            if (!options.catalogOnly) Object.assign(entry, await measure(dependencies, objectKey, stored, signal));
            if (entry.durationMs !== null) {
                if (stored?.format === 'unsupported') entry.set['mediaRepresentation.durationMs'] = entry.durationMs;
                entry.set.duration = formatDuration(entry.durationMs / 1000);
            }
            counts[entry.result] = (counts[entry.result] ?? 0) + 1;
            await dependencies.record(entry);
            if (candidates === options.limit) return { type: 'summary', dryRun: true, finished: false, resumeAfter: cursor, scanned, candidates, counts };
        }
        if (page.length < pageSize) return { type: 'summary', dryRun: true, finished: true, resumeAfter: null, scanned, candidates, counts };
    }
};

/** Downloads and decodes one source; cancellation rethrows, every other failure becomes a bounded reason. */
const measure = async (dependencies: AudioDurationBackfillDependencies, objectKey: string,
    stored: ReturnType<typeof storedMediaRepresentationForTrack>, signal?: AbortSignal)
    : Promise<Pick<AudioDurationBackfillEntry, 'result' | 'reason' | 'durationMs'>> => {
    const directory = await mkdtemp(join(tmpdir(), 'archtree-duration-backfill-'));
    try {
        const path = join(directory, 'source');
        const pin = stored ? { etag: stored.etag!, versionId: stored.versionId, byteLength: stored.byteLength } : null;
        let size: Awaited<ReturnType<typeof downloadSource>>;
        try { size = await downloadSource(dependencies, objectKey, pin, path, signal); }
        catch (error) {
            signal?.throwIfAborted();
            const status = s3Status(error);
            return { result: status === 404 || status === 412 ? 'stale' : 'failed',
                reason: status === 404 || status === 412 ? 'source_changed' : 'storage_unavailable', durationMs: null };
        }
        if (size === 'stale') return { result: 'stale', reason: 'source_changed', durationMs: null };
        if (size === 'unprobeable') return { result: 'unprobeable', reason: null, durationMs: null };
        try {
            const durationMs = await dependencies.probe({ path, size, buffer: undefined } as unknown as Express.Multer.File, { signal });
            return durationMs === null ? { result: 'unprobeable', reason: null, durationMs } : { result: 'wouldUpdate', reason: null, durationMs };
        } catch (error) {
            signal?.throwIfAborted();
            return { result: 'failed', reason: error instanceof RoomAudioInspectionError ? error.code : 'analysis_failed', durationMs: null };
        }
    } finally { await rm(directory, { recursive: true, force: true }); }
};
